import sys

data = list(map(int, sys.stdin.buffer.read().split()))
n, m = data[0], data[1]
adj = [[] for _ in range(n + 1)]

idx = 2
for _ in range(m):
    a, b = data[idx], data[idx + 1]
    idx += 2
    adj[a].append(b)
    adj[b].append(a)

del data

visited = bytearray(n + 1)

for start in range(1, n + 1):
    if visited[start]:
        continue

    visited[start] = 1
    stack = [start]
    component = []
    degree_sum = 0

    while stack:
        u = stack.pop()
        component.append(u)
        degree_sum += len(adj[u])
        for v in adj[u]:
            if not visited[v]:
                visited[v] = 1
                stack.append(v)

    size = len(component)
    if degree_sum < size * (size - 1):
        for u in component:
            if len(adj[u]) < size - 1:
                marked = bytearray(n + 1)
                for v in adj[u]:
                    marked[v] = 1
                for v in component:
                    if v != u and not marked[v]:
                        print(u, v)
                        sys.exit(0)

print(-1)
